-- ======================================================================== 05_views.sql
-- 05_views.sql: views the demo reads. Seed tables hold day offsets; these views turn them into dates relative to today,
-- so "last night" and "due next week" are true on whatever day you present.

CREATE OR REPLACE VIEW werkbank_demo.fin.v_margin_vs_plan (
  month COMMENT 'First day of the month.',
  quarter COMMENT 'Calendar quarter label such as Q3 2026.',
  region_code COMMENT 'Sales region: DACH, UKI, FR or NORDICS.',
  product_line COMMENT 'Product line.',
  revenue_eur COMMENT 'Actual gross revenue in EUR.',
  revenue_plan_eur COMMENT 'Planned gross revenue in EUR.',
  discount_eur COMMENT 'Actual discounts in EUR.',
  discount_plan_eur COMMENT 'Planned discounts in EUR.',
  cogs_eur COMMENT 'Actual cost of goods sold in EUR.',
  cogs_plan_eur COMMENT 'Planned cost of goods sold in EUR.',
  fx_cost_eur COMMENT 'Actual FX cost in EUR.',
  fx_cost_plan_eur COMMENT 'Planned FX cost in EUR.',
  net_revenue_eur COMMENT 'Actual revenue minus discounts in EUR. Denominator of gross margin %.',
  plan_net_revenue_eur COMMENT 'Planned revenue minus discounts in EUR.',
  gross_margin_eur COMMENT 'Actual gross margin in EUR: revenue - discount - cogs - fx cost.',
  plan_gross_margin_eur COMMENT 'Planned gross margin in EUR.',
  gross_margin_pct COMMENT 'Actual gross margin as % of net revenue. For several rows compute SUM(gross_margin_eur) / SUM(net_revenue_eur); never average this column.',
  plan_gross_margin_pct COMMENT 'Planned gross margin as % of net revenue. For several rows compute SUM(plan_gross_margin_eur) / SUM(plan_net_revenue_eur).',
  margin_delta_pp COMMENT 'Actual minus planned gross margin % in percentage points; negative is below plan. Only meaningful for one row; for several rows recompute from the sums.',
  margin_delta_eur COMMENT 'Actual minus planned gross margin in EUR; negative is below plan. This one can be summed.'
)
COMMENT 'Gross margin against plan by month, region and product line. Use the EUR columns and ratios of sums when aggregating. Row-level security by region applies when governance is enabled.'
AS
SELECT
  month,
  concat('Q', quarter(month), ' ', year(month)) AS quarter,
  region_code,
  product_line,
  revenue_eur,
  revenue_plan_eur,
  discount_eur,
  discount_plan_eur,
  cogs_eur,
  cogs_plan_eur,
  fx_cost_eur,
  fx_cost_plan_eur,
  revenue_eur - discount_eur AS net_revenue_eur,
  revenue_plan_eur - discount_plan_eur AS plan_net_revenue_eur,
  revenue_eur - discount_eur - cogs_eur - fx_cost_eur AS gross_margin_eur,
  revenue_plan_eur - discount_plan_eur - cogs_plan_eur - fx_cost_plan_eur AS plan_gross_margin_eur,
  round(100 * (revenue_eur - discount_eur - cogs_eur - fx_cost_eur) / (revenue_eur - discount_eur), 2) AS gross_margin_pct,
  round(100 * (revenue_plan_eur - discount_plan_eur - cogs_plan_eur - fx_cost_plan_eur) / (revenue_plan_eur - discount_plan_eur), 2) AS plan_gross_margin_pct,
  round(
    100 * (revenue_eur - discount_eur - cogs_eur - fx_cost_eur) / (revenue_eur - discount_eur)
    - 100 * (revenue_plan_eur - discount_plan_eur - cogs_plan_eur - fx_cost_plan_eur) / (revenue_plan_eur - discount_plan_eur),
    2
  ) AS margin_delta_pp,
  (revenue_eur - discount_eur - cogs_eur - fx_cost_eur)
    - (revenue_plan_eur - discount_plan_eur - cogs_plan_eur - fx_cost_plan_eur) AS margin_delta_eur
FROM werkbank_demo.fin.margin_monthly;

CREATE OR REPLACE VIEW werkbank_demo.scm.purchase_orders (
  po_number COMMENT 'Ten-digit purchase order number.',
  item COMMENT 'Item number.',
  material COMMENT 'Material id.',
  material_description COMMENT 'Material description.',
  vendor_id COMMENT 'Vendor id.',
  vendor_name COMMENT 'Vendor name.',
  plant COMMENT 'Plant id.',
  plant_name COMMENT 'Plant name.',
  buyer_id COMMENT 'Buyer id.',
  buyer_name COMMENT 'Buyer name.',
  quantity COMMENT 'Ordered quantity.',
  unit_price_eur COMMENT 'Unit price in EUR.',
  net_value_eur COMMENT 'Quantity times unit price in EUR.',
  order_date COMMENT 'Order date.',
  requested_delivery_date COMMENT 'Delivery date the business asked for.',
  confirmed_delivery_date COMMENT 'Delivery date the vendor confirmed.',
  days_confirmed_after_requested COMMENT 'Days the vendor confirmed later than requested; 0 when on time.',
  inbound_lane COMMENT 'Origin and destination country.',
  lane_congested COMMENT '1 when the lane has a customs or port backlog.',
  status COMMENT 'OPEN or PARTIALLY_DELIVERED.'
)
COMMENT 'Open purchase orders with dates relative to today. This is the gold table the nightly load publishes.'
AS
SELECT
  s.po_number,
  s.item,
  s.material,
  s.material_description,
  s.vendor_id,
  v.vendor_name,
  s.plant,
  s.plant_name,
  s.buyer_id,
  s.buyer_name,
  s.quantity,
  s.unit_price_eur,
  round(s.quantity * s.unit_price_eur, 2) AS net_value_eur,
  date_add(current_date(), s.order_offset_days) AS order_date,
  date_add(current_date(), s.requested_offset_days) AS requested_delivery_date,
  date_add(current_date(), s.confirmed_offset_days) AS confirmed_delivery_date,
  greatest(s.confirmed_offset_days - s.requested_offset_days, 0) AS days_confirmed_after_requested,
  s.inbound_lane,
  s.lane_congested,
  s.status
FROM werkbank_demo.scm.purchase_orders_seed s
JOIN werkbank_demo.scm.vendors v ON v.vendor_id = s.vendor_id;

CREATE OR REPLACE VIEW werkbank_demo.ops.job_runs (
  run_id COMMENT 'Run id.',
  job_id COMMENT 'Job id.',
  job_name COMMENT 'Job name.',
  owner_team COMMENT 'Team that owns the job.',
  start_time COMMENT 'When the run started.',
  end_time COMMENT 'When the run ended.',
  duration_minutes COMMENT 'Run duration in minutes.',
  result_state COMMENT 'SUCCESS or FAILED.'
)
COMMENT 'Job runs of the last 14 nights with timestamps relative to now. Shaped like system.lakeflow.job_run_timeline.'
AS
SELECT run_id, job_id, job_name, owner_team, start_time, timestampadd(MINUTE, duration_minutes, start_time) AS end_time, duration_minutes, result_state
FROM (
  SELECT
    r.run_id,
    r.job_id,
    j.job_name,
    j.owner_team,
    to_timestamp(concat(cast(date_add(current_date(), r.start_day_offset) AS STRING), ' ', lpad(cast(r.start_hour AS STRING), 2, '0'), ':', lpad(cast(r.start_minute AS STRING), 2, '0'), ':00')) AS start_time,
    r.duration_minutes,
    r.result_state
  FROM werkbank_demo.ops.job_runs_seed r
  JOIN werkbank_demo.ops.jobs j ON j.job_id = r.job_id
) runs
WHERE start_time <= current_timestamp();

-- ======================================================================== 06_model_view.sql
-- 06_model_view.sql: the stand-in for a Model Serving endpoint.
-- A transparent logistic score over four features, so the demo is deterministic and every number can be explained.
-- In a real landscape replace this view with ai_query('<your-endpoint>', ...) over the same features: the UC functions
-- that read it (07_functions.sql) and the agent recipes stay unchanged.

CREATE OR REPLACE VIEW werkbank_demo.scm.v_po_delay_scores (
  po_number COMMENT 'Ten-digit purchase order number.',
  item COMMENT 'Item number.',
  buyer_id COMMENT 'Buyer id.',
  vendor_id COMMENT 'Vendor id.',
  vendor_name COMMENT 'Vendor name.',
  material_description COMMENT 'What is ordered.',
  quantity COMMENT 'Ordered quantity.',
  net_value_eur COMMENT 'Order value in EUR.',
  requested_delivery_date COMMENT 'Date the business asked for.',
  confirmed_delivery_date COMMENT 'Date the vendor confirmed.',
  delay_probability COMMENT 'Probability of a late delivery, 0 to 1. Above 0.6 is high risk.',
  expected_delay_days COMMENT 'Expected delay in days.',
  top_drivers COMMENT 'The two largest reasons for the score, separated by semicolons.'
)
COMMENT 'Delay-risk score for every open purchase order. Logistic model: -1.6 + 6 x (0.9 - vendor on-time-in-full) + 0.22 x days confirmed late + 1.1 x max(order size / vendor capacity - 0.8, 0) + 0.9 x lane backlog.'
AS
WITH features AS (
  SELECT
    p.po_number,
    p.item,
    p.buyer_id,
    p.vendor_id,
    p.vendor_name,
    p.material_description,
    p.quantity,
    p.net_value_eur,
    p.requested_delivery_date,
    p.confirmed_delivery_date,
    CAST(v.otif_90d AS DOUBLE) AS otif_90d,
    CAST(p.days_confirmed_after_requested AS DOUBLE) AS confirm_gap_days,
    CAST(p.quantity AS DOUBLE) / v.monthly_capacity_units AS load_ratio,
    CAST(p.lane_congested AS DOUBLE) AS lane_congested
  FROM werkbank_demo.scm.purchase_orders p
  JOIN werkbank_demo.scm.vendors v ON v.vendor_id = p.vendor_id
  WHERE p.status IN ('OPEN', 'PARTIALLY_DELIVERED')
),
contributions AS (
  SELECT
    f.*,
    6 * (0.9 - otif_90d) AS c_otif,
    0.22 * confirm_gap_days AS c_gap,
    1.1 * greatest(load_ratio - 0.8, 0) AS c_load,
    0.9 * lane_congested AS c_lane
  FROM features f
),
scored AS (
  SELECT c.*, 1 / (1 + exp(-(-1.6 + c_otif + c_gap + c_load + c_lane))) AS probability
  FROM contributions c
)
SELECT
  po_number,
  item,
  buyer_id,
  vendor_id,
  vendor_name,
  material_description,
  quantity,
  net_value_eur,
  requested_delivery_date,
  confirmed_delivery_date,
  round(probability, 3) AS delay_probability,
  round(probability * 9, 1) AS expected_delay_days,
  array_join(
    transform(
      slice(
        sort_array(
          filter(
            array(
              named_struct('score', c_otif, 'label', 'Vendor on-time-in-full rate is low'),
              named_struct('score', c_gap, 'label', 'Vendor confirmed later than requested'),
              named_struct('score', c_load, 'label', 'Order size is close to vendor capacity'),
              named_struct('score', c_lane, 'label', 'Inbound lane has a customs backlog')
            ),
            x -> x.score > 0
          ),
          false
        ),
        1,
        2
      ),
      x -> x.label
    ),
    '; '
  ) AS top_drivers
FROM scored;

-- ======================================================================== 07_functions.sql
-- 07_functions.sql: Unity Catalog SQL functions. Through the Databricks managed MCP endpoint for functions each
-- one becomes a typed tool; the function COMMENT is the tool description and the parameter COMMENTs are the
-- argument descriptions. That text is what the agent reads, so it says when to use the tool, what it returns,
-- what it does not do and which argument means what.
-- SQL functions are read-only by construction: none of them can change data.
--
-- Parameter names are chosen so they never equal a column name (buyer, top_n, po, days_back, job_run_id, table_name).

-- ---------------------------------------------------------------- scm

CREATE OR REPLACE FUNCTION werkbank_demo.scm.get_delay_risk_pos(
  buyer STRING COMMENT 'Buyer id such as B-100. An id, not a name.',
  top_n INT DEFAULT 5 COMMENT 'How many purchase orders to return, from 1 to 20. Default 5.'
)
RETURNS TABLE (
  po_number STRING COMMENT 'Ten-digit purchase order number; the key to use in SAP.',
  item STRING COMMENT 'Item number.',
  vendor_id STRING COMMENT 'Vendor id.',
  vendor_name STRING COMMENT 'Vendor name.',
  material_description STRING COMMENT 'What is ordered.',
  quantity INT COMMENT 'Ordered quantity.',
  net_value_eur DOUBLE COMMENT 'Order value in EUR.',
  requested_delivery_date DATE COMMENT 'Date the business asked for.',
  confirmed_delivery_date DATE COMMENT 'Date the vendor confirmed.',
  delay_probability DOUBLE COMMENT 'Probability of a late delivery, 0 to 1. Above 0.6 is high risk.',
  expected_delay_days DOUBLE COMMENT 'Expected delay in days if it is late.',
  top_drivers STRING COMMENT 'The one or two main reasons for the score, separated by semicolons.'
)
COMMENT 'Returns the open purchase orders of ONE buyer that are most likely to be delivered late, highest risk first, each with its two main reasons. Use it when a buyer asks which orders are at risk, which will slip or what to expedite. It scores open orders with the delay-risk model and changes nothing. It does not draft or send any request; use the SAP tools for that, with the po_number it returns.'
RETURN
  SELECT
    po_number,
    item,
    vendor_id,
    vendor_name,
    material_description,
    quantity,
    CAST(net_value_eur AS DOUBLE) AS net_value_eur,
    requested_delivery_date,
    confirmed_delivery_date,
    delay_probability,
    expected_delay_days,
    top_drivers
  FROM (
    SELECT s.*, row_number() OVER (ORDER BY s.delay_probability DESC, s.po_number) AS risk_rank
    FROM werkbank_demo.scm.v_po_delay_scores s
    WHERE s.buyer_id = buyer
  ) ranked
  WHERE risk_rank <= least(greatest(coalesce(top_n, 5), 1), 20)
  ORDER BY risk_rank;

CREATE OR REPLACE FUNCTION werkbank_demo.scm.get_po_detail(
  po STRING COMMENT 'Ten-digit purchase order number such as 4500001007.'
)
RETURNS TABLE (
  po_number STRING COMMENT 'Purchase order number.',
  item STRING COMMENT 'Item number.',
  vendor_name STRING COMMENT 'Vendor name.',
  vendor_otif_90d DOUBLE COMMENT 'Vendor on-time-in-full rate over 90 days, 0 to 1.',
  material_description STRING COMMENT 'What is ordered.',
  quantity INT COMMENT 'Ordered quantity.',
  requested_delivery_date DATE COMMENT 'Date the business asked for.',
  confirmed_delivery_date DATE COMMENT 'Date the vendor confirmed.',
  days_confirmed_after_requested INT COMMENT 'Days the vendor confirmed later than requested.',
  inbound_lane STRING COMMENT 'Origin and destination country.',
  lane_congested INT COMMENT '1 when the lane has a customs or port backlog.',
  delay_probability DOUBLE COMMENT 'Probability of a late delivery, 0 to 1. Empty when the order is not scored.',
  top_drivers STRING COMMENT 'Main reasons for the score.'
)
COMMENT 'Returns one purchase order with the facts behind its delay-risk score: vendor performance, confirmed versus requested date, lane backlog and the main drivers. Use it to explain why one specific order is at risk after get_delay_risk_pos has found it. Reads only; for the live SAP record use the SAP tools.'
RETURN
  SELECT
    p.po_number,
    p.item,
    p.vendor_name,
    CAST(v.otif_90d AS DOUBLE) AS vendor_otif_90d,
    p.material_description,
    p.quantity,
    p.requested_delivery_date,
    p.confirmed_delivery_date,
    CAST(p.days_confirmed_after_requested AS INT) AS days_confirmed_after_requested,
    p.inbound_lane,
    p.lane_congested,
    s.delay_probability,
    s.top_drivers
  FROM werkbank_demo.scm.purchase_orders p
  JOIN werkbank_demo.scm.vendors v ON v.vendor_id = p.vendor_id
  LEFT JOIN werkbank_demo.scm.v_po_delay_scores s ON s.po_number = p.po_number AND s.item = p.item
  WHERE p.po_number = po;

